        let store = TaskStore::open_in_memory().unwrap();
        store.insert("cgt-010", "prompt a", "standard").unwrap();
        store.insert("cgt-011", "prompt b", "standard").unwrap();
        store.update_status("cgt-010", "succeeded", None).unwrap();
