    fn validate_too_many_videos() {
        let mut args = default_args();
        let spec = models::resolve_spec(&args.model);
        args.video = (0..4).map(|i| format!("https://vid/{i}.mp4")).collect();
        assert!(validate_inputs(&args, &spec).is_err());
    }

