#[derive(Debug, Clone, Serialize)]
pub struct ImageGenRequest {
    pub model: String,
    pub prompt: String,
    /// Reference images for i2i / editing / multi-image fusion
    /// (URLs or base64 data URIs; max 10)
    #[serde(skip_serializing_if = "Vec::is_empty")]
