use anyhow::{Context, Result};
use reqwest::header::{HeaderMap, HeaderValue, AUTHORIZATION, CONTENT_TYPE};
use types::{CreateTaskRequest, ImageGenRequest, ImageGenResponse, TaskResponse};

pub struct ArkClient {
    http: reqwest::Client,
    base_url: String,
}

impl ArkClient {
    pub fn new(base_url: &str, api_key: &str) -> Result<Self> {
        let mut headers = HeaderMap::new();
        headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&format!("Bearer {api_key}"))
                .context("invalid API key characters")?,
        );

        let http = reqwest::Client::builder()
            .default_headers(headers)
            .timeout(std::time::Duration::from_secs(30))
            .build()?;

        Ok(Self {
            http,
            base_url: base_url.trim_end_matches('/').to_string(),
        })
    }

    pub async fn create_task(&self, req: &CreateTaskRequest) -> Result<TaskResponse> {
        let url = format!(
            "{}/contents/generations/tasks",
            self.base_url
        );

        let resp = self.http.post(&url).json(req).send().await?;
        let status = resp.status();

        if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
            anyhow::bail!(error::ArkError::RateLimited);
        }

        let body = resp.text().await?;

        if !status.is_success() {
            anyhow::bail!(error::ArkError::Api {
                status: status.as_u16(),
                message: body,
            });
        }

        let task: TaskResponse =
            serde_json::from_str(&body).with_context(|| format!("failed to parse response: {body}"))?;
        Ok(task)
    }

    pub async fn query_task(&self, task_id: &str) -> Result<TaskResponse> {
        let url = format!(
            "{}/contents/generations/tasks/{task_id}",
            self.base_url
        );

        let resp = self.http.get(&url).send().await?;
        let status = resp.status();

        if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
            anyhow::bail!(error::ArkError::RateLimited);
        }

        let body = resp.text().await?;

        if !status.is_success() {
            anyhow::bail!(error::ArkError::Api {
                status: status.as_u16(),
                message: body,
            });
        }

        let task: TaskResponse =
            serde_json::from_str(&body).with_context(|| format!("failed to parse response: {body}"))?;
        Ok(task)
    }

    /// Generate images (Seedream) via the synchronous
    /// POST /images/generations endpoint. Image generation can take
    /// tens of seconds, so this uses a longer per-request timeout.
    pub async fn generate_image(&self, req: &ImageGenRequest) -> Result<ImageGenResponse> {
        let url = format!("{}/images/generations", self.base_url);

        let resp = self
            .http
            .post(&url)
            .json(req)
            .timeout(std::time::Duration::from_secs(300))
            .send()
            .await?;
        let status = resp.status();

        if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
            anyhow::bail!(error::ArkError::RateLimited);
        }

        let body = resp.text().await?;

        if !status.is_success() {
            anyhow::bail!(error::ArkError::Api {
                status: status.as_u16(),
                message: body,
            });
        }

        serde_json::from_str(&body).with_context(|| format!("failed to parse response: {body}"))
    }
}

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize)]
pub struct CreateTaskRequest {
    pub model: String,
    pub content: Vec<ContentItem>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub resolution: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ratio: Option<String>,
    /// Duration in seconds; `-1` lets the model pick (Seedance 2.5)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub duration: Option<i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub watermark: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub generate_audio: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub seed: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub return_last_frame: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub callback_url: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tools: Option<Vec<Tool>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub service_tier: Option<String>,
    /// Task type for Seedance 2.5+: "generate" / "edit" / "extend"
    #[serde(skip_serializing_if = "Option::is_none")]
    pub task_type: Option<String>,
    /// Output container: "mp4" (default) or "mov" (Seedance 2.5+)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub output_format: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Tool {
    #[serde(rename = "type")]
    pub tool_type: String,
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ContentItem {
    Text {
        text: String,
    },
    ImageUrl {
        image_url: UrlRef,
        #[serde(skip_serializing_if = "Option::is_none")]
        role: Option<String>,
    },
    VideoUrl {
        video_url: UrlRef,
        #[serde(skip_serializing_if = "Option::is_none")]
        role: Option<String>,
    },
    AudioUrl {
        audio_url: UrlRef,
        #[serde(skip_serializing_if = "Option::is_none")]
        role: Option<String>,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UrlRef {
    pub url: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct TaskResponse {
    pub id: String,
    #[serde(default)]
    pub object: String,
    #[serde(default)]
    pub model: String,
    #[serde(default)]
    pub status: String,
    pub video_url: Option<String>,
    /// Some APIs return `url` instead of `video_url`
    pub url: Option<String>,
    pub content: Option<TaskContent>,
    pub error: Option<ApiError>,
    pub usage: Option<Usage>,
    pub created_at: Option<i64>,
    pub updated_at: Option<i64>,
}

