        assert_eq!(upload::guess_mime("photo.jpeg"), "image/jpeg");
        assert_eq!(upload::guess_mime("photo.JPEG"), "image/jpeg");
        assert_eq!(upload::guess_mime("photo.png"), "image/png");
        assert_eq!(upload::guess_mime("photo.webp"), "image/webp");
