    fn validate_max_images_ok() {
        let mut args = default_args();
        let spec = models::resolve_spec(&args.model);
        args.image = (0..9).map(|i| format!("https://img/{i}.jpg")).collect();
        assert!(validate_inputs(&args, &spec).is_ok());
    }

