        assert!(validate_inputs(&args, &spec).is_ok());

        args.video = vec!["https://v.mp4".into(), "https://v2.mp4".into()];
        // 9 + 2 + 1 + 1 = 13, FAIL
        assert!(validate_inputs(&args, &spec).is_err());
    }
