        let cli = TestCli::try_parse_from([
            "test",
            "--source-video", "v1.mp4",
            "--source-video", "v2.mp4",
            "--source-video", "v3.mp4",
            "视频1打开门，接视频2，镜头推进，接视频3",
        ])
